    /* the bag's total is never half-cut. The foot repeats the saving only while the ledger's saving row is out of view; if the
       Total row is not wholly in view, its figure moves into the foot's first line. */
    var sv = $('#drfoot p.sv'), off = $('.dr-tot .off'), tt = $('.dr-tot .tt'), s = stat(bag);
    if (sv && tt) {
      var vis = function (e) { return e.getBoundingClientRect().bottom <= body.getBoundingClientRect().bottom; };
      sv.hidden = true; tt.style.display = '';
      if (!vis(tt)) { tt.style.display = 'none'; sv.hidden = false; sv.innerHTML = 'Total ' + R(s.total) + ' · you save ' + R(s.sub - s.total); }
